import numpy as np
t=df['t'];P=df['P'];y=df['dP_dt']
names=[];cols=[]
def add(n,v): names.append(n); cols.append(v)
for pn,pv in [('P',P),('P2',P**2),('P3',P**3),('1/P',1/P),('1/P2',1/P**2),('P0',np.ones_like(P))]:
    for tn,tv in [('1',np.ones_like(t)),('t',t),('t2',t**2),('e-t',np.exp(-t)),('lnt',np.log(t))]:
        add(pn+'*'+tn,pv*tv)
X=np.array(cols).T
c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
print(np.mean((X@c-y)**2)/np.var(y))
for n,v in zip(names,c):
    if abs(v)>1e-3: print(n,round(v,4))
